    59	function useViolations(violations: TransactionViolation[], shouldShowOnlyViolations: boolean) {
    60	    const violationsByField = useMemo((): ViolationsMap => {
    61	        const filteredViolations = violations.filter((violation) => {
    62	            if (excludedViolationsName.includes(violation.name)) {
    63	                return false;
    64	            }
    65	            if (shouldShowOnlyViolations) {
